/**
 * Migration round-trip check: upgrade → downgrade → upgrade.
 *
 * A migration that cannot be reversed is not finished. This also catches the
 * specific failure that bit us once already: Alembic's autogenerated downgrade
 * drops tables but NOT Postgres ENUM types, so the second upgrade dies with
 * `DuplicateObject: type "..." already exists` and the database is stuck until
 * someone drops them by hand.
 *
 * Lived in CI until Actions stopped running reliably. It matters more than the
 * rest of the suite, so it moved to `pnpm verify` where it actually executes.
 */

import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const backend = path.join(repoRoot, "backend");

const alembic =
  process.platform === "win32"
    ? path.join(backend, ".venv", "Scripts", "alembic.exe")
    : path.join(backend, ".venv", "bin", "alembic");

if (!existsSync(alembic)) {
  console.error(`Alembic not found at ${alembic}\nRun: cd backend && python -m venv .venv && ...`);
  process.exit(1);
}

function run(label, args) {
  process.stdout.write(`  ${label.padEnd(22)}`);
  const r = spawnSync(alembic, args, { cwd: backend, encoding: "utf8" });
  const output = `${r.stdout ?? ""}${r.stderr ?? ""}`;
  if (r.status !== 0 || /error|Traceback/i.test(output)) {
    console.log("FAIL");
    console.error(output.split("\n").slice(-25).join("\n"));
    return false;
  }
  console.log("ok");
  return true;
}

console.log("Migration round-trip:");
const ok =
  run("upgrade head", ["upgrade", "head"]) &&
  run("downgrade base", ["downgrade", "base"]) &&
  run("upgrade head", ["upgrade", "head"]);

if (!ok) {
  console.error(
    "\nRound-trip failed. If the second upgrade died on a duplicate type, the\n" +
      "downgrade is not dropping its ENUMs — see the initial migration for the\n" +
      "DROP TYPE block that fixes this.",
  );
  process.exit(1);
}

// `downgrade base` drops every table, so the demo data goes with it. Several
// tests assert against that data — the sibling groups, the van carrying six
// children from four families, the one-time pass — so the check has to restore
// what it destroyed or it breaks the suite that runs after it.
const python =
  process.platform === "win32"
    ? path.join(backend, ".venv", "Scripts", "python.exe")
    : path.join(backend, ".venv", "bin", "python");

process.stdout.write("  reseed demo data      ");
const seed = spawnSync(python, ["../scripts/seed.py", "--reset"], {
  cwd: backend,
  encoding: "utf8",
});
if (seed.status !== 0) {
  console.log("FAIL");
  console.error(`${seed.stdout ?? ""}${seed.stderr ?? ""}`.split("\n").slice(-20).join("\n"));
  process.exit(1);
}
console.log("ok");

console.log("Migration round-trip clean.\n");
